#include <LiquidCrystal.h>

// Подключение: RS, E, D4, D5, D6, D7
LiquidCrystal lcd(12, 11, 5, 4, 3, 2);

void setup() {
  lcd.begin(16, 2);

  // Очистка и вывод крупного текста для лучшей видимости
  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print("TEST OK");

  lcd.setCursor(0, 1);
  lcd.print("UID: 12345678");
}

void loop() {
  // Мигаем для привлечения внимания (опционально)
  delay(1000);
}
